import {chromium} from '/home/node/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs';
import assert from 'node:assert/strict';

const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const context = await browser.newContext({locale: 'en-US', viewport: {width: 1280, height: 960}});
const page = await context.newPage();
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5174');
await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
assert.equal(await page.locator('html').getAttribute('lang'), 'en');
await page.locator('.language-option').filter({hasText: 'Русский'}).click();
await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
assert.equal(await page.locator('html').getAttribute('lang'), 'ru');
assert.equal(await page.title(), 'Настройки языка · Рабочее пространство');
assert.equal(await page.evaluate(() => localStorage.getItem('app-language')), 'ru');
assert.equal(await page.locator('.quick-language input[value=\"ru\"]').isChecked(), true);
await page.reload();
await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
await page.screenshot({path: '/tmp/language-desktop.png', fullPage: true});
await page.getByRole('radio', {name: 'EN', exact: true}).check();
await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
assert.equal(await page.locator('.language-options input[value=\"en\"]').isChecked(), true);
await page.locator('.language-options input[value=\"en\"]').focus();
await page.keyboard.press('ArrowRight');
await page.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
for (const width of [320, 375, 768]) {
  await page.setViewportSize({width, height: 900});
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true, "'`No overflow at ${width}px`);
}
await page.setViewportSize({width: 375, height: 900});
await page.screenshot({path: '"'/tmp/language-mobile.png', fullPage: true});
await page.evaluate(() => localStorage.setItem('app-language', 'fr'));
await page.reload();
await page.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
await context.close();

const russianContext = await browser.newContext({locale: 'ru-RU'});
const russianPage = await russianContext.newPage();
await russianPage.goto('http://localhost:5174');
await russianPage.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
await russianPage.evaluate(() => localStorage.setItem('app-language', 'en'));
await russianPage.reload();
await russianPage.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
await russianContext.close();

const blockedContext = await browser.newContext({locale: 'en-US'});
await blockedContext.addInitScript(() => {
  Object.defineProperty(window, 'localStorage', {get() {throw new DOMException('Storage blocked', 'SecurityError');}});
});
const blockedPage = await blockedContext.newPage();
blockedPage.on('pageerror', error => errors.push(error.message));
await blockedPage.goto('http://localhost:5174');
await blockedPage.getByRole('heading', {name: 'Settings', exact: true}).waitFor();
await blockedPage.getByRole('radio', {name: 'RU', exact: true}).check();
await blockedPage.getByRole('heading', {name: 'Настройки', exact: true}).waitFor();
await blockedPage.getByRole('status').filter({hasText: 'Браузер не позволяет сохранить выбор'}).waitFor();
assert.deepEqual(errors, []);
await browser.close();
console.log('PASS: switching both directions, synchronized controls, keyboard navigation, persistence, initial locale, invalid preference, blocked storage, responsive widths, no runtime errors.');
EOF"

